// Copy the browser-safe core of the client SDK (client/src) into the web
// client (permutation-server/web/sdk), which loads it as plain ES modules
// with no build step. The copies are generated: edit client/src and run this
// again (test/web-sdk.test.mjs fails while they differ).
//
// The Frontier (M1) part has one more step in front (contract §3.3: JS gets
// the ABI's constants only through generated files):
//
//   frontier-abi/vectors/*.json  ──►  client/src/frontier/abi-*.mjs   (generated here)
//   client/src/frontier/*.mjs    ──►  web/sdk/frontier/*.mjs          (copied here)
//
// `web/sdk/vendor/` belongs to scripts/vendor-noble.mjs (W2-E) and is left
// alone; test/web-sdk.test.mjs checks its manifest.
//
//   node scripts/sync-web-sdk.mjs           write the generated files
//   node scripts/sync-web-sdk.mjs --check   only report; exit 1 if anything is out of date
import { existsSync, mkdirSync, readdirSync, readFileSync, realpathSync, rmSync, statSync, writeFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';

/** The browser-safe set: no node:*, no Buffer, no web3.js or ER SDK, relative imports within the set only. */
export const WEB_SDK = Object.freeze(['sha256.mjs', 'base58.mjs', 'bytes.mjs', 'borsh.mjs', 'codec.mjs', 'decision.mjs', 'talk.mjs', 'batch.mjs',
  'offices.mjs', 'solana-tx.mjs', 'player.mjs']);
export const HEADER = '// generated by permutation-gateway/scripts/sync-web-sdk.mjs — edit permutation-gateway/client/src';
export const SOURCE_DIR = fileURLToPath(new URL('../client/src/', import.meta.url));
export const WEB_SDK_DIR = fileURLToPath(new URL('../../permutation-server/web/sdk/', import.meta.url));

/** Subdirectories of web/sdk: `frontier/` is written here, `vendor/` by scripts/vendor-noble.mjs. The flat sync removes neither. */
export const WEB_SDK_DIRS = Object.freeze(['frontier', 'vendor']);

// ------------------------------------------------------------------ Frontier (M1)

export const ABI_VECTORS_DIR = fileURLToPath(new URL('../../frontier-abi/vectors/', import.meta.url));
export const FRONTIER_SOURCE_DIR = fileURLToPath(new URL('../client/src/frontier/', import.meta.url));
export const WEB_FRONTIER_DIR = fileURLToPath(new URL('../../permutation-server/web/sdk/frontier/', import.meta.url));
/** The first line of a module generated from an ABI vector file (then the source file's name). */
export const ABI_HEADER = '// generated by permutation-gateway/scripts/sync-web-sdk.mjs from frontier-abi/vectors/';

const pick = (o, keys) => Object.fromEntries(keys.filter(k => k in o).map(k => [k, o[k]]));

/**
 * The modules generated from frontier-abi's vectors: module → {from, name
 * (the export), keep (what of the vector file the browser needs)}. Only
 * data: the code that reads it is hand-written (codec, budgets, shapes…).
 */
export const FRONTIER_GENERATED = Object.freeze({
  'abi-tags.mjs': { from: 'tags.json', name: 'TAGS', keep: v => pick(v, ['abi_version', 'contract', 'instructions', 'reserved_tags', 'constants']) },
  'abi-errors.mjs': { from: 'errors.json', name: 'ERRORS', keep: v => pick(v, ['abi_version', 'contract', 'errors']) },
  'abi-budgets.mjs': { from: 'budgets.json', name: 'BUDGETS', keep: v => pick(v, ['abi_version', 'contract', 'constants', 'instructions']) },
  'abi-layouts.mjs': { from: 'layouts.json', name: 'LAYOUTS', keep: v => pick(v, ['abi_version', 'contract', 'accounts', 'records', 'season_params', 'rent_per_byte', 'season_tombstone_size', 'reserved_magic']) },
  'abi-presets.mjs': { from: 'presets.json', name: 'PRESETS', keep: v => pick(v, ['abi_version', 'contract', 'quicknet', 'ruleset_hash', 'payout_params_rev3_borsh', 'presets']) },
});

/** The hand-written Frontier SDK modules (client/src/frontier), in dependency order. */
export const FRONTIER_MODULES = Object.freeze(['budgets.mjs', 'fees.mjs', 'codec.mjs', 'addresses.mjs', 'seal.mjs', 'shapes.mjs', 'herald.mjs']);
/** Everything web/sdk/frontier holds. */
export const WEB_SDK_FRONTIER = Object.freeze([...Object.keys(FRONTIER_GENERATED), ...FRONTIER_MODULES]);

/** A generated module's text for `vector` (the parsed JSON file). Deterministic: same JSON, same bytes. */
export function abiModule(file, vector) {
  const g = FRONTIER_GENERATED[file];
  return `${ABI_HEADER}${g.from} — do not edit; run: node permutation-gateway/scripts/sync-web-sdk.mjs
// Data only (contract §3.3: JS gets the ABI's constants through generated files).
const freeze = o => { if (o && typeof o === 'object' && !Object.isFrozen(o)) { Object.freeze(o); for (const v of Object.values(o)) freeze(v); } return o; };
export const ${g.name} = freeze(${JSON.stringify(g.keep(vector))});
export default ${g.name};
`;
}

/** What client/src/frontier's generated modules should hold: file name → content. */
export function expectedAbi(dir = ABI_VECTORS_DIR) {
  return new Map(Object.entries(FRONTIER_GENERATED).map(([file, g]) => [file, abiModule(file, JSON.parse(readFileSync(dir + g.from, 'utf8')))]));
}

// ------------------------------------------------------------------ checks

/** Module specifiers a source imports or re-exports (static and dynamic). */
export function importsOf(source) {
  const out = [];
  for (const re of [/\b(?:import|export)\s[^'"`;]*?\bfrom\s*['"]([^'"]+)['"]/g, /\bimport\s*['"]([^'"]+)['"]/g, /\bimport\s*\(\s*['"]([^'"]+)['"]\s*\)/g]) {
    for (const m of source.matchAll(re)) out.push(m[1]);
  }
  return out;
}

/** Source without comments (enough for these modules: none has `//` or `/*` inside a string). */
export const stripComments = source => source.replace(/\/\*[\s\S]*?\*\//g, '').replace(/(^|[^:'"\\])\/\/.*$/gm, '$1');

/**
 * Why `source` (file `name`) cannot run in a browser as part of the set;
 * empty when it can. A Frontier module (`frontier: true`) may import its
 * siblings in the Frontier set and, one level up, the flat set.
 */
export function problems(name, source, { frontier = false } = {}) {
  const out = [];
  const code = stripComments(source);
  for (const spec of importsOf(code)) {
    if (spec.startsWith('node:')) out.push(`${name}: imports ${spec}`);
    else if (frontier && spec.startsWith('../')) {
      if (!WEB_SDK.includes(spec.slice(3))) out.push(`${name}: imports ${spec}, which is not in the web set`);
    } else if (!spec.startsWith('./')) out.push(`${name}: imports ${spec} (bare or outside the directory)`);
    else if (!(frontier ? WEB_SDK_FRONTIER : WEB_SDK).includes(spec.slice(2))) out.push(`${name}: imports ${spec}, which is not in the web set`);
  }
  if (/\bBuffer\b/.test(code)) out.push(`${name}: uses Buffer`);
  if (/\bprocess\./.test(code) || /\brequire\s*\(/.test(code)) out.push(`${name}: uses a Node global`);
  return out;
}

/** What web/sdk should hold: file name → content. */
export function expected() {
  return new Map(WEB_SDK.map(name => [name, `${HEADER}\n${readFileSync(SOURCE_DIR + name, 'utf8')}`]));
}

/** What web/sdk/frontier should hold, given client/src/frontier's generated modules as `abi` (file → content). */
export function expectedFrontier(abi = expectedAbi()) {
  const source = name => abi.get(name) ?? readFileSync(FRONTIER_SOURCE_DIR + name, 'utf8');
  return new Map(WEB_SDK_FRONTIER.map(name => [name, `${HEADER}\n${source(name)}`]));
}

const isDir = p => existsSync(p) && statSync(p).isDirectory();
const differs = (dir, name, content) => !existsSync(dir + name) || readFileSync(dir + name, 'utf8') !== content;

/**
 * Compare (and unless `check`, write) `want` (name → content) into `dir`.
 * `keepDirs`: subdirectories that are not this set's to remove. Returns the
 * names that were (or would be) written and removed.
 */
function syncDir(dir, want, { check, keepDirs = [] }) {
  const have = existsSync(dir) ? readdirSync(dir) : [];
  const stale = have.filter(f => !want.has(f) && !(keepDirs.includes(f) && isDir(dir + f)));
  const changed = [...want].filter(([name, content]) => differs(dir, name, content)).map(([name]) => name);
  if (!check) {
    mkdirSync(dir, { recursive: true });
    for (const f of stale) rmSync(dir + f, { recursive: true, force: true });
    for (const name of changed) writeFileSync(dir + name, want.get(name));
  }
  return { changed, stale };
}

function main() {
  const check = process.argv.includes('--check');
  const want = expected();
  const abi = expectedAbi();
  const frontier = expectedFrontier(abi);
  const bad = [...[...want].flatMap(([name, content]) => problems(name, content)),
    ...[...frontier].flatMap(([name, content]) => problems(`frontier/${name}`, content, { frontier: true }))];
  if (bad.length) {
    console.error(`not browser-safe:\n  ${bad.join('\n  ')}`);
    process.exit(1);
  }
  // client/src/frontier: only the generated modules are ours (the rest is hand-written).
  const gen = [...abi].filter(([name, content]) => differs(FRONTIER_SOURCE_DIR, name, content)).map(([name]) => name);
  const flat = syncDir(WEB_SDK_DIR, want, { check: true, keepDirs: WEB_SDK_DIRS });
  const fr = syncDir(WEB_FRONTIER_DIR, frontier, { check: true });
  if (check) {
    const out = [...gen.map(f => `client/src/frontier/${f} (from frontier-abi/vectors)`), ...flat.changed, ...flat.stale.map(f => `${f} (not in the set)`),
      ...fr.changed.map(f => `frontier/${f}`), ...fr.stale.map(f => `frontier/${f} (not in the set)`)];
    if (!out.length) { console.log(`web/sdk is up to date (${want.size} files, frontier/ ${frontier.size}, ${abi.size} generated from frontier-abi)`); return; }
    console.error(`web/sdk is out of date: ${out.join(', ')}\nrun: node permutation-gateway/scripts/sync-web-sdk.mjs`);
    process.exit(1);
  }
  mkdirSync(FRONTIER_SOURCE_DIR, { recursive: true });
  for (const name of gen) writeFileSync(FRONTIER_SOURCE_DIR + name, abi.get(name));
  const a = syncDir(WEB_SDK_DIR, want, { check: false, keepDirs: WEB_SDK_DIRS });
  const b = syncDir(WEB_FRONTIER_DIR, frontier, { check: false });
  console.log(`client/src/frontier: ${gen.length} generated; web/sdk: ${a.changed.length} written, ${a.stale.length} removed; `
    + `web/sdk/frontier: ${b.changed.length} written, ${b.stale.length} removed`);
}

if (process.argv[1] && realpathSync(fileURLToPath(import.meta.url)) === realpathSync(process.argv[1])) main();
